/* Expanded teaching notes. Loaded after platform-data; original IDs and practice remain intact. */
(() => {
 'use strict';
 const note=(heading,paragraphs)=>`<div class="deep-notes"><h3>${esc(heading)}</h3>${paragraphs.map(p=>`<p>${p}</p>`).join('')}</div>`;
 const add=(course,id,heading,...paragraphs)=>{
   for(const lesson of courses[course].lessons){
     const topic=lesson.sections.find(s=>s.id===id);
     if(topic) topic.html+=note(heading,paragraphs);
   }
 };
 const a=(id,title,...p)=>add('html',id,title,...p);
 a('html-1','إيه اللي بيحصل لما الصفحة بتتفتح؟',
 'المتصفح برنامج بيقرأ ملفات الموقع وبيحوّل وصفها لواجهة. لما تفتح عنوان على الإنترنت، بيطلب الملفات من خادم عبر HTTP. الخادم هو البرنامج اللي بيرد على الطلبات. ملف HTML يحدد المحتوى، وروابط داخله ممكن تطلب CSS وJavaScript وصور. فتح ملف محلي مباشر بيقرأ من جهازك بدل طلب الملف من خادم.',
 'الواجهة الأمامية، أو Frontend، هي الكود اللي بيكوّن الواجهة ويتفاعل في المتصفح. الواجهة الخلفية، أو Backend، بتعالج طلبات وتخزين وصلاحيات على الخادم. مش كل صفحة محتاجة Backend خاص. HTML بتوصف تركيب الوثيقة؛ مفيهاش شروط وتكرار بنفس معنى لغة JavaScript.',
 'المتصفح بيحلّل HTML ويبني DOM، وهي شجرة تمثل العناصر. بعد حساب قواعد CSS بيحدد مقاسات ومواقع العناصر، وبعدها يرسمها. لذلك الملف النصي والواجهة المرئية مش نفس الشيء: الملف مصدر، والواجهة نتيجة معالجة المتصفح. أدوات المطوّر بتخلّيك تفحص النتيجة وتعرف مصدر التنسيق.');
 a('html-2','إنشاء الملفات وتشغيلها وفحصها',
 'اعمل فولدر خاص بالمشروع، وافتح الفولدر في محرر الكود. أنشئ index.html وتأكد إن الامتداد فعلاً html، مش html.txt. الاسم index شائع لصفحة الدخول لكنه مش كلمة إلزامية في لغة HTML. حفظ الملف في المحرر بيغيّر المصدر؛ تحديث المتصفح هو اللي يقرأ التعديل، إلا لو أداة المعاينة بتعمل تحديث تلقائي.',
 'خلي الصور وملفات CSS وJavaScript جوه فولدر المشروع. المسار بيتحسب بالنسبة للملف أو عنوان الصفحة حسب مكان الاستخدام؛ نقل ملف من فولدر لفولدر ممكن يكسر روابطه. الأحرف الكبيرة والصغيرة في أسماء الملفات قد تفرق على الاستضافة حتى لو جهازك سمح بالاختلاف.',
 'افتح أدوات المطوّر من قائمة المتصفح. Elements بتعرض DOM، وConsole بتعرض الرسائل وأخطاء JavaScript، وNetwork بتعرض طلبات الملفات وحالاتها. تغيير DOM من Elements تجربة مؤقتة؛ لو عايز تعديل دائم ارجع لملف المصدر واحفظه.');
 a('html-3','نفصل الوسم والعنصر والخاصية',
 'في الصيغة <code>&lt;p class="intro"&gt;نص&lt;/p&gt;</code>، وسم البداية هو الجزء الأول، ووسم النهاية فيه الشرطة المائلة، والعنصر هو التركيب كله. اسم p يحدد نوع العنصر. class خاصية، وintro قيمتها. الخصائص بتتكتب داخل وسم البداية، مش بعده وسط المحتوى.',
 'العناصر ممكن تحتوي نصًا وعناصر أخرى حسب قواعد العنصر. لازم الإغلاق يعكس ترتيب الفتح: العنصر الداخلي يقفل قبل الخارجي. المسافة البادئة في الكود بتوضح التعشيش للمبرمج، لكنها مش بديل عن تركيب صحيح. المتصفح أحيانًا بيصحح تركيب غلط تلقائيًا، فظهور الصفحة مش إثبات إن المصدر سليم.',
 'استخدم علامات اقتباس حول قيم الخصائص. التعليق بيبدأ بـ<code>&lt;!--</code> وينتهي بـ<code>--&gt;</code> ولا يظهر كنص في الصفحة. لعرض الرمز &lt; نفسه اكتب <code>&amp;lt;</code>، ولعرض &amp; اكتب <code>&amp;amp;</code>. دي مراجع محارف، علشان الرمز مايتفهمش كجزء من تركيب HTML.');
 a('html-4','عناصر المحتوى والعناصر الفارغة',
 'العناصر العادية زي p وbutton لها محتوى بين البداية والنهاية. أما Void elements زي img وinput وbr وmeta وlink فمش بتقبل محتوى أبناء، ومفيش وسم إغلاق لها في HTML. كتابة <code>&lt;/img&gt;</code> مش مطلوبة ومش طريقة صحيحة لتمثيل صورة.',
 'الشرطة المائلة في <code>&lt;img /&gt;</code> لا تجعل عنصر HTML عادي ذاتي الإغلاق. مثلًا <code>&lt;div /&gt;</code> مش بديل عن إغلاق div في HTML. في JSX القاعدة مختلفة وبتلزمك تقفل العنصر؛ لازم تربط القاعدة باللغة اللي بتكتبها.',
 'في عناصر HTML معينة المتصفح يسمح بحذف وسم النهاية في حالات محددة، لكن للمبتدئ الإغلاق الصريح أوضح. ما تعتمدش على إصلاح المتصفح عشان كودك يشتغل؛ التعشيش الغلط ممكن يغيّر DOM عن ترتيب الكود ويصعّب التنسيق والاختيار بـJavaScript.');
 a('html-5','دور كل جزء في هيكل الوثيقة',
 'DOCTYPE تصريح في أول الملف بيطلب وضع المعايير من المتصفح، مش عنصر محتوى. html هو الجذر، وlang يحدد لغة المحتوى لأدوات القراءة والمعالجة، وdir يحدد اتجاه الكتابة. اللغة العربية مش معناها إن اتجاه أي كلمة إنجليزية هيتظبط تلقائيًا؛ المحتوى المختلط محتاج عزل اتجاه عند اللزوم.',
 'head فيها معلومات الوثيقة: ترميز UTF-8، عنوان التبويب title، وصف الصفحة، وروابط التنسيق. body فيها المحتوى والتفاعل اللي بيظهر في الصفحة. meta viewport بتضبط مساحة تخطيط الصفحة على أجهزة الموبايل؛ من غيرها ممكن المتصفح يستخدم عرض افتراضي كبير ويصغّر الصفحة كلها.',
 'اكتب charset بدري في head واحفظ الملف بترميز UTF-8. title مش بديل لعنوان h1، وmeta description مش فقرة مرئية في body. ملف HTML وحده مش محتاج أمر build؛ أدوات البناء تدخل لما تستخدم نظامًا بيحتاج تحويل أو تجميع ملفات.');
 a('html-6','ترتيب العناوين والتصفح بينها',
 'مستوى العنوان يعكس ترتيب الموضوع. h1 عنوان رئيسي للصفحة، h2 أقسامها، وh3 أجزاء داخل قسم h2. الرقم مش عدد مرات ظهور العنوان؛ تقدر تكتب أكتر من h2 لأنهم في نفس المستوى. اختيار مستوى أصغر لمجرد تصغير الشكل بيخلط معنى الوثيقة بتنسيقها.',
 'عنوان مناسب لازم يقول محتوى الجزء اللي بعده. قارئ الشاشة يقدر يتنقل بالعناوين، فالعناوين المبهمة أو القفز العشوائي بين المستويات بيصعّب التصفح. استخدم CSS للتحكم في الحجم والوزن والمسافة، مع الحفاظ على التسلسل الدلالي.',
 'لو عنوانك طويل خليه يلف بشكل طبيعي بدل br كتير مرتبطة بعرض جهازك. ما تستخدمش فقرة غامقة كبديل عن عنوان حقيقي. افحص الصفحة بدون CSS: المفروض يفضل واضح فين الأقسام الرئيسية وفين التفاصيل الفرعية.');
 a('html-7','النص داخل الفقرة بيتحلّل إزاي؟',
 'p تمثل فقرة نصية، مش صندوق عام لأي عناصر. المتصفح بيختصر أغلب المسافات والأسطر في مصدر HTML لمسافة واحدة في العرض العادي. لذلك الضغط على Enter داخل المصدر مش معناه فاصل سطر في النتيجة. كل فقرة جديدة تبقى p مستقلة.',
 'br لفاصل سطر له معنى في نفس النص، وليس مسافة بين أقسام. المسافة بين الفقرات مسؤولية margin. hr يمثل انتقالًا موضوعيًا في المحتوى، مش مجرد خط ديكوري؛ الخطوط الزخرفية ممكن تعملها بـCSS.',
 'ما تحطش div أو عنوان جوه p؛ محلل HTML ممكن يقفل الفقرة تلقائيًا قبل العنصر، فتتفاجئ بشجرة مختلفة. استخدم pre لو الفراغات وترتيب السطور جزء من المحتوى زي كود، ومع code لتوضيح إن النص مقطع برمجي.');
 a('html-8','الدلالة مختلفة عن الشكل الافتراضي',
 'strong يحدد أهمية قوية، وem يحدد تأكيدًا في النص. المتصفح عادة يعرض الأول غامق والتاني مائل، لكن المعنى مش متوقف على الشكل ده. b يلفت الانتباه بدون نفس دلالة الأهمية، وi له استخدامات اصطلاحية مختلفة، زي كلمة مميزة عن سياق الكلام.',
 'mark يميز جزءًا مرتبطًا بسياق القراءة الحالي. del يوضح نصًا محذوفًا، وins إضافة. sub وsup لمحتوى منخفض أو مرتفع عن خط الكتابة، وsmall لتعليق جانبي. اختار العنصر اللي يصف دور النص، مش عنصر تجمع منه شكلًا بصريًا فقط.',
 'تنسيقات كتير في نفس الفقرة تقلّل وضوح الأولويات. خليك في تأكيد له سبب، واستعمل CSS لتغيير اللون والوزن. استخدام عنوان أو زرار داخل عنصر نصي لمجرد الاستفادة من شكله مش تنظيم صحيح للمحتوى.');
 a('html-9','أنواع المسارات وسلوك الروابط',
 'href عنوان الوجهة. العنوان الكامل زي https://example.com/about بيحدد المصدر كله. المسار النسبي about.html محسوب من عنوان الصفحة الحالية، و../ يرجع مستوى للأعلى. المسار اللي يبدأ / بيتحسب من جذر الموقع؛ عند فتح ملف محلي جذر الملفات مش هو فولدر مشروعك، فاختبر طريقة التشغيل اللي هتستخدمها.',
 'الرابط اللي يبدأ # بينتقل لعنصر id مطابق في الوثيقة، أو تستخدمه تطبيقات الصفحة الواحدة لتحديد شاشة. id لازم يكون فريدًا داخل الصفحة. ما تستخدمش href فارغة أو # بديلًا لزرار ينفذ فعلًا؛ زرار button أوضح للتفاعل، وa للتنقل.',
 'نص الرابط لازم يشرح وجهته، وحالة التركيز لازم تبقى واضحة. target يختار سياق الفتح، وrel ينظم العلاقة ببعض الحالات. download يطلب تنزيل مورد في الحالات المسموحة، لكنه مش ضمان تنزيل أي رابط خارجي؛ المتصفح وسياسات المصدر لهم دور.');
 a('html-10','تحميل الصور ونسبتها والنص البديل',
 'src يحدد مورد الصورة. المتصفح يطلب المسار، فلو رجع 404 معناها المورد غير موجود في العنوان ده. راجع الاسم والامتداد ومكان الملف. رفع HTML من غير فولدر الصور لا ينقل الصور تلقائيًا للاستضافة.',
 'alt يشرح المعلومة اللي الصورة بتوصلها، مش شرحًا عامًا لكل تفاصيلها. لو الصورة داخل رابط ومفيش نص تاني، وصفها لازم يوضح وظيفة الرابط. الصورة الزخرفية البحتة alt فارغة علشان ما تزودش كلام غير مفيد لقارئ الشاشة.',
 'حدد width وheight بنسبة الصورة علشان المتصفح يحجز مساحتها قبل التحميل. بعد كده CSS مثل max-width:100% وheight:auto يمنع تجاوز الحاوية ويحافظ على النسبة. loading="lazy" يؤخر صور بعيدة عن أول الشاشة؛ صورة البداية المهمة غالبًا مايناسبهاش التأخير.');
 a('html-11','بنية القوائم والتداخل الصحيح',
 'ul مجموعة عناصر لا يغير معناها ترتيبها، وol مجموعة ترتيبها مهم. كل عنصر مباشر في النوعين يكون li. لو محتاج قائمة فرعية، حطها داخل li اللي تتبعها، مش أختًا عشوائية لعناصر li خارج مكانها.',
 'dl تنظيم لأسماء وأوصاف: dt للمصطلح وdd لشرحه. دي مش طريقة تعمل بيها مسافات بادئة؛ استخدمها لما العلاقة فعلًا اسم ووصف. ظهور الترقيم أو النقط في القوائم العادية تنسيق افتراضي تقدر تغيره بـCSS من غير تغيير نوع القائمة.',
 'خاصية start في ol تبدأ العد من رقم تختاره، وreversed تعكس اتجاه العد. الترقيم المرئي مش بيانات تخزّنها في كل li يدويًا. خليك واضح في أسماء العناصر، وتجنب تحويل كل قائمة في الصفحة إلى divs لأنك كده بتفقد معناها البنيوي.');
 a('html-12','التجميع لا يضيف وظيفة تلقائيًا',
 'div حاوية عامة لمجموعة محتوى، وspan حاوية نصية عامة داخل السطر. الاتنين لوحدهم لا يضيفوا معنى زر أو رابط أو عنوان. ينفع تضيف class علشان تختارهم بالتنسيق، أو id فريد للربط والاختيار.',
 'الأب هو العنصر الحاوي مباشرة، والأبناء عناصر جواه؛ العناصر الموجودة على نفس المستوى إخوة. العلاقة دي مهمة لأن CSS ممكن تستهدف الابن المباشر، وJavaScript ممكن يتحرك بين العلاقات. زيادة الحاويات من غير وظيفة بتعقّد الشجرة.',
 'قبل إضافة div اسأل هل فيه عنصر يصف المعنى زي article أو nav؟ لو مفيش، div مناسبة للتجميع. ما تحطش div مكان button وتكتفي بمستمع ضغط؛ هتحتاج تعيد سلوك لوحة المفاتيح والتركيز والدلالة اللي button بتوفره أصلًا.');
 a('html-13','التدفق الطبيعي وصناديق العرض',
 'Block وInline أوضاع عرض افتراضية، مش تقسيم لكل عنصر للأبد. العنصر block في التدفق العادي يبدأ في سطر مستقل وعرضه التلقائي يستفيد من المساحة المتاحة. inline يشارك السطر ويتجزأ عبر السطور مع النص.',
 'width وheight لا يتحكموا في span النصية العادية بنفس طريقة صندوق block. inline-block يشارك السطر لكن يسمح بمقاسات صندوق مستقلة. الصور عناصر مستبدلة وليها أبعاد داخلية، فلا تعمم سلوك span على img.',
 'تغيير display لا يصلح تعشيش HTML غير صالح ولا يغيّر دلالة العنصر لأدوات المساعدة. ممكن تخلي رابط block ويبقى رابطًا. افصل سؤالين: العنصر معناه إيه؟ وصندوقه بيتحرك في التخطيط إزاي؟');
 a('semantic','الحدود بين الأقسام الدلالية',
 'main يحدد المحتوى الرئيسي المميز للصفحة. nav لتجميع روابط تنقل أساسية، مش كل مجموعة روابط صغيرة. article محتوى مستقل يمكن فهمه خارج الصفحة، وsection جزء موضوعي غالبًا يحدده عنوان. div لو التجميع للتنسيق فقط.',
 'header مقدمة الصفحة أو القسم، وfooter ختام الصفحة أو القسم؛ لذلك وجود أكتر من واحد مش خطأ تلقائيًا. المهم مكانه ودوره. aside لمحتوى مرتبط بشكل جانبي. العناصر دي مش بتعمل التخطيط بصريًا؛ CSS هي اللي ترتبها.',
 'الدلالة بتساعد التصفح لكن مش كفاية وحدها لسهولة الوصول. ترتيب منطقي، أسماء روابط واضحة، حقول مسمّاة، تركيز ظاهر، وألوان مقروءة كلها مطلوبة. ARIA توضح معنى إضافيًا لما تحتاجه؛ ما تستبدلش عنصر HTML مناسب بدور مكتوب يدويًا بلا سبب.');
 a('html-14','قراءة الجدول حسب علاقات البيانات',
 'table تنظّم بيانات لكل منها تقاطع صف وعمود. tr يجمع خلايا صف واحد. td بيانات، وth عنوان بيانات. مكان الخلية في المصدر بيساهم في مكانها في الشبكة؛ لازم عدد الأعمدة المنطقي يفضل متسقًا بعد حساب الدمج.',
 'caption عنوان للجدول كله، وscope يوضح اتجاه علاقة خلية العنوان: col للعمود وrow للصف. الشكل الغامق الافتراضي لـth مش السبب لاختيارها. العلاقة بين العنوان والبيانات هي اللي تهم أدوات المساعدة.',
 'الجداول مش أداة تخطيط صفحة الموقع. لو الجدول أعرض من شاشة الموبايل، وفر حاوية تمرير أفقي محلية بدل خروج الصفحة كلها. ما تصغّرش النص لدرجة تمنع القراءة، وحافظ على تمييز الصفوف والعناوين.');
 a('html-15','أقسام الجدول والتنسيق الصحيح',
 'thead يجمع صفوف العنوان، tbody صفوف البيانات، وtfoot صفوف الملخص. دول مجموعات صفوف، مش خلايا؛ لذلك تحط داخلهم tr، وداخل tr تحط th أو td. المتصفح ممكن يضيف tbody عند تحليل صفوف مباشرة في table، فافحص DOM لو المحددات مش مطابقة.',
 'الحدود تُضبط بـborder، والمسافات داخل الخلايا بـpadding. border-collapse:collapse يدمج الحدود المشتركة؛ separate يخلي الحدود منفصلة ومعاه border-spacing. الخصائص القديمة في HTML للتنسيق مش الأسلوب اللي نبني عليه شغل جديد.',
 'في الجدول المعقد عناوين متعددة المستويات محتاجة ربط أدق، وممكن headers تشير لمعرفات خلايا th. قبل التعقيد حاول تبسط البيانات. زيادة الأقسام وحدها مش «احتراف»؛ وضوح معنى كل عمود وعلاقة خلاياه هو الهدف.');
 a('html-16','احسب أماكن الخلايا بعد الدمج',
 'colspan عدد الأعمدة اللي الخلية تمتد عليها في نفس الصف. لو الجدول ٣ أعمدة وخلية colspan="2"، يبقى فاضل مكان خلية واحدة في الصف ده. ما تكتبش خلايا إضافية لنفس المساحة المحجوزة.',
 'rowspan عدد الصفوف اللي الخلية تمتد عليها. في الصف اللي بعدها المساحة دي محجوزة، فبتكتب الخلايا الباقية فقط. ارسم شبكة بسيطة وحدد مكان كل خلية قبل كتابة الدمج؛ الأخطاء هنا بتبان في عدد المساحات، مش بالضرورة رسالة خطأ.',
 'الدمج لازم يعكس البيانات مش مجرد شكل. كثرة rowspan وcolspan بتصعّب متابعة العلاقة على الموبايل وقارئ الشاشة. اختبر العناوين والترتيب بعد الدمج، وخلي الملخص والعناوين واضحين بدون الاعتماد على اللون فقط.');
 a('html-17','من اسم الحقل لطلب الإرسال',
 'form يجمع عناصر إدخال مرتبطة بهدف إرسال واحد. action عنوان المعالجة، وmethod طريقة الطلب. GET يضع البيانات في عنوان الطلب، وPOST يرسلها في جسم الطلب. POST وحده لا يشفر الاتصال؛ HTTPS هو اللي يوفر حماية النقل.',
 'id هوية داخل الوثيقة لربط label واختيار العنصر. name اسم المفتاح اللي يُرسل مع قيمة الحقل. ممكن id وname يختلفوا لأن وظائفهم مختلفة. حقل من غير name غالبًا مش هيشارك في بيانات الإرسال التقليدي.',
 'button داخل form افتراضيًا قد يرسلها، لذلك صرّح بـtype. submit يطلب الإرسال، وbutton لفعل عادي، وreset يرجع الافتراضيات. المتصفح ينفذ التحقق القياسي قبل إرسال صالح؛ اعتراض submit بـJavaScript له شرح مستقل في مسار الأحداث.');
 a('html-18','نوع الحقل وسلوك المتصفح',
 'type يحدد سلوكًا وواجهة مناسبة. email يطبق تحقق صيغة مبدئي، وnumber يوفر إدخالًا رقميًا بقواعده، وdate قد يوفر منتقي تاريخ. شكل العنصر ممكن يختلف بين المتصفحات. رقم التليفون الأفضل غالبًا tel لأنه معرّف مش كمية حسابية وقد يبدأ بصفر أو علامة +.',
 'password يخفي النص بصريًا لكنه لا يحفظه مشفرًا. file يسمح باختيار ملفات؛ الاختيار مش رفعًا تلقائيًا. رفع الملف التقليدي يحتاج form بإعداد enctype مناسب ومعالجة خادم، أو كود يرسل البيانات بالطريقة المناسبة.',
 'اختار النوع حسب معنى المدخل، ثم اختبره على جهاز لمس ولوحة مفاتيح. ما تعتمدش على شكل لوحة مفاتيح الهاتف كتحقق نهائي. أي بيانات توصل للخادم تحتاج فحصًا عنده حتى لو قيود المتصفح منعت أخطاء بسيطة أثناء الاستخدام العادي.');
 a('html-19','فرق القيمة الافتراضية والقيود',
 'value في HTML تحدد قيمة بداية لبعض الحقول، بينما القيمة الحالية تتغير لما المستخدم يكتب. placeholder تلميح مؤقت داخل الحقل مش بديل لاسم label. required يمنع الإرسال الفارغ وفق نوع الحقل، لكنه مش شرط يمنع نص مسافات في حقل نصي.',
 'min وmax وstep قيود رقمية أو زمنية حسب النوع. minlength وmaxlength قيود طول في أنواع نصية مناسبة، وpattern نمط تحقق له صياغة خاصة. اشرح القيود للمستخدم قبل الخطأ، واعرض رسالة واضحة لما لا تتحقق.',
 'disabled يمنع التفاعل العادي ويستبعد الحقل من الإرسال التقليدي. readonly يمنع تحرير أنواع حقول تدعمه لكن القيمة تظل قابلة للإرسال والتركيز. autocomplete يساعد الإكمال؛ اختيار قيمة مناسبة يحسّن الاستخدام. ما تغيّرش قيودًا بدون فهم أثرها على الإرسال والتركيز.');
 a('html-20','اسم المجموعة وقيمة الاختيار',
 'radio مناسبة لاختيار واحد من مجموعة. عناصر المجموعة لها نفس name، وكل خيار له value مختلفة وid منفصلة لربط label. لما المستخدم يحدد واحدًا، البقية في نفس المجموعة تلغي تحديدها تلقائيًا.',
 'checkbox كل واحدة لها حالة مستقلة. checked في HTML تحدد البداية، وفي JavaScript خاصية checked تعطي الحالة الحالية. عند الإرسال التقليدي الاختيارات غير المحددة عادة لا تُرسل؛ لازم المعالج يفهم غياب المفتاح. من غير value قد تُرسل القيمة الافتراضية on.',
 'fieldset يجمع حقولًا مترابطة، وlegend عنوان المجموعة. ده أوضح من فقرة بعيدة عن الاختيارات. خلي الضغط على النص يحدد الاختيار عن طريق label، وحافظ على حالة التركيز ولا تعتمد على اللون وحده لمعرفة المحدد.');
 a('html-21','اختيار متعدد الأسطر أو من خيارات',
 'textarea للنص متعدد الأسطر؛ قيمة البداية في HTML بين وسم الفتح والإغلاق، مش attribute اسمها value. القيمة الحالية في JavaScript تُقرأ من .value. rows تقترح عدد سطور مرئية، مش حدًا لعدد الأسطر اللي المستخدم يقدر يكتبها.',
 'select تحتوي option، والنص المرئي للخيار ممكن يختلف عن value المُرسلة. selected تحدد اختيار البداية في HTML. multiple تسمح باختيارات متعددة وقد تعرض واجهة مختلفة. optgroup تجمع خيارات تحت عنوان داخل القائمة.',
 'اربط label بكل عنصر واذكر هل الاختيار مطلوب. في React controlled textarea وselect بيستخدموا value على العنصر نفسه بدل قواعد القيمة الابتدائية في HTML؛ التفرقة بين المصدرين مهمة لما توصل لمسار React.');

 const c=(id,title,...p)=>add('css',id,title,...p);
 c('css-1','ربط CSS ومكان تطبيقها',
 'CSS لغة قواعد تحوّل العناصر لصناديق ذات ألوان ومقاسات وتخطيط. ربط ملف خارجي يكون بعنصر link داخل head مع rel="stylesheet" وhref لمسار الملف. كتابة المسار لا تنسخ الملف؛ لازم يكون متاحًا عند التشغيل والنشر.',
 'القواعد داخل style تخص الوثيقة، وstyle attribute يضع تصريحات على عنصر واحد. الملف الخارجي أنسب لتجميع قواعد مشتركة. لو التنسيق مش ظاهر راجع طلب الملف في Network، ثم مطابقة المحدد، ثم القاعدة الفائزة في Styles. غياب الأثر لا يعني إن الملف مش متحمّل بالضرورة.');
 c('css-2','من المحدد للتصريح والقيمة',
 'القاعدة تتكون من محدد ثم أقواس معقوفة تحتوي تصريحات. كل تصريح اسم خاصية ثم نقطتين ثم قيمة، والفاصلة المنقوطة تفصل التصريحات. الخاصية زي color، والقيمة زي purple. الاسم والقيمة لازم يكونوا صالحين حسب قواعد الخاصية.',
 'المتصفح عادة يتجاهل تصريحًا غير صالح بدل إيقاف ملف CSS كله. لكن قوسًا ناقصًا ممكن يغير تحليل مجموعة أكبر. التعليقات تبدأ بـ/* وتنتهي بـ*/. في أدوات المطوّر القيمة المشطوبة قد تكون غير صالحة أو مهزومة بقاعدة أخرى؛ اقرأ السبب قبل تعديل أرقام عشوائية.');
 c('css-3','المطابقة والأولوية والوراثة',
 'محدد النوع مثل p يطابق الاسم، و.card يطابق وجود class، و#intro يطابق id. class ممكن تتكرر على عناصر كتير، والعنصر ممكن يحمل أكتر من class بمسافات. id فريد داخل الوثيقة. مطابقة عنصرين لنفس المحدد مش معناها إنهم نفس العنصر.',
 'لو أكثر من تصريح ينافس على نفس الخاصية، Cascade تحسم حسب عوامل منها الأصل والأهمية والطبقات ثم Specificity ثم ترتيب الظهور عند التعادل. لا تحفظ إن آخر سطر يفوز دائمًا؛ المقارنة بالترتيب تأتي بعد عوامل أسبق.',
 'بعض الخصائص تورث مثل color عادة، وأخرى مثل margin لا تورث افتراضيًا. القيمة الموروثة مش قاعدة بتغلب تصريحًا مباشرًا صالحًا على العنصر. تجنب !important كحل أول؛ افحص القاعدة ومحددها ومكانها ثم صلّح سبب التعارض.');
 c('css-4','حجم الخط وارتفاع السطر ووحداته',
 'font-family قائمة بدائل؛ المتصفح يستخدم أول خط متاح يحتوي المحارف المطلوبة. طلب خط خارجي قد يفشل أو يتأخر، فوجود بديل مناسب مهم. font-weight يحدد السمك إذا كان الوزن متاحًا، وfont-size حجم الحروف، وليس ارتفاع كل سطر بمفرده.',
 'line-height يحدد ارتفاع صندوق السطر. الرقم بلا وحدة يتناسب مع حجم خط كل عنصر وارث، فغالبًا يبقى مرنًا. قيمة 2 تعني ضعف حجم الخط لهذا العنصر. اختبر نصًا عربيًا حقيقيًا لأن اتصال الحروف والتشكيل يختلف عن النص اللاتيني.');
 c('css-5','لف النص واتجاهه وتجاوز مساحته',
 'text-align يحدد المحاذاة، وdirection يحدد الاتجاه الأساسي، لكن خلط كود إنجليزي مع عربي يحتاج عزلًا مثل bdi. لا تعكس جملة كاملة علشان اسم دالة؛ اعزل المقطع اللاتيني واترك الفقرة عربية.',
 'white-space يحدد التعامل مع الفراغات واللف. overflow-wrap:anywhere يساعد كسر عنوان أو رابط طويل داخل مساحة ضيقة. letter-spacing الزائد غير مناسب غالبًا للعربي لأنه يؤثر على الاتصال. text-overflow:ellipsis يحتاج شروط قص وعرض مناسبة؛ مش اختصارًا سحريًا لأي نص.');
 c('css-10','الصورة كخلفية أم كمحتوى؟',
 'background لا يضيف عنصر صورة ولا نصًا بديلًا. لو الصورة بتوصل معلومة أساسية اختار img وalt مناسبين. لو زخرفة فخلفية CSS مناسبة. رابط الصورة داخل CSS النسبي يُحسب من ملف CSS نفسه، وليس دائمًا من ملف HTML.',
 'cover يغطي مساحة الحاوية مع المحافظة على النسبة وقد يقص أطرافًا. contain يعرض الصورة كاملة وقد يترك فراغًا. position يحدد موضعها وrepeat يحدد التكرار. لون خلفية احتياطي ضروري لو الصورة فشلت، وتباين النص فوقها لازم يظل واضحًا في كل المقاسات.');
 c('css-6','المحتوى والحشو الداخلي في الحساب',
 'كل صندوق له منطقة محتوى، ثم padding حولها، ثم border، وبعدها margin. padding مسافة داخل الحد، لذلك خلفية العنصر تمتد فيها حسب قواعد الرسم. زيادة padding تقلل المساحة المتبقية للمحتوى داخل عرض ثابت مع border-box.',
 'الصيغة المختصرة بأربع قيم ترتيبها أعلى ثم يمين ثم أسفل ثم يسار. بقيمتين: الأولى أعلى وأسفل، والثانية يمين ويسار. استخدم padding-inline وpadding-block لما تقصد اتجاه النص بدل جانب مادي ثابت، خصوصًا في موقع عربي.');
 c('css-7','الهامش الخارجي وحدود الصندوق',
 'border له عرض ونوع ولون؛ لو النوع none فلن يظهر حد حتى لو كتبت اللون. margin خارج الحد ويؤثر على الفصل بين الصناديق، وخلفية العنصر لا تلوّنه. margin:auto أفقيًا قد يوسّط صندوقًا مناسبًا بعرض أضيق من حاويته، ومش قاعدة توسّط كل عنصر في كل تخطيط.',
 'في التدفق العادي بعض الهوامش الرأسية بين صناديق block بتنهار معًا بدل جمعها؛ ده اسمه Margin collapse. داخل Flexbox وGrid القواعد مختلفة والهوامش بين الأبناء ما تنهارش بالطريقة دي. استخدم gap للمسافة المنتظمة بين عناصر تخطيط بدل ملاحقة margin لكل عنصر.');
 c('css-8','حساب العرض خطوة بخطوة',
 'مع content-box قيمة width تخص المحتوى. لو width=200 وpadding أفقي 20 لكل جانب وborder=2 لكل جانب، العرض حتى الحد الخارجي يصبح 244. margin لو موجود خارج الحساب ده. مع border-box نفس width=200 تشمل المحتوى والحشو والحد.',
 'border-box لا يضمن عدم خروج عنصر من الصفحة؛ ممكن min-width أو محتوى غير قابل للكسر يمنع الانكماش. من المفيد قاعدة عامة تشمل العناصر والعناصر الوهمية، لكن لازم تفهم الحساب مش تكتبها كتعويذة. أدوات المطور فيها رسم للصندوق يعرض القياسات الفعلية.');
 c('css-9','كل وحدة مرجعها مختلف',
 'px بكسل CSS، مش لازم بكسل شاشة فعلي بسبب كثافة العرض والتكبير. rem نسبة لحجم خط الجذر، وem في font-size نسبة لحجم خط الأب، وفي كثير من القياسات الأخرى لحجم خط العنصر نفسه. لذلك القيم النسبية محتاجة تعرف مرجعها قبل الحساب.',
 '% مرتبطة بالخاصية والحاوية؛ ما تفترضش نفس المرجع لكل الخصائص. vw نسبة من عرض مساحة العرض وvh من ارتفاعها. على الموبايل dvh يتبع الارتفاع المتغير، وsvh يرتبط بالمساحة الصغيرة. اختيار وحدة نسبية وحده لا يضمن تجاوبًا؛ الحدود واللف والمحتوى جزء من الحل.');
 c('css-11','display يغيّر توزيع الصناديق',
 'block وinline وinline-block توضح وضع الصندوق بالنسبة للمحيط. flex وgrid يحددان نظام ترتيب للأبناء المباشرين داخل الحاوية. تغيير display للأب لا يحوّل كل الأحفاد تلقائيًا لعناصر flex؛ العلاقة المباشرة مهمة.',
 'خاصية display لا تغيّر معنى العنصر في HTML عادة، لكن بعض حالات الإخفاء تؤثر على شجرة الوصول. لو غرضك ترتيب زرين في صف اعمل حاوية مناسبة بدل تغيير معنى العناصر. افحص الفرق بين صندوق العنصر وسلوك أبنائه.');
 c('css-12','اختفاء الشكل والتخطيط والتفاعل',
 'display:none يخرج الصندوق من التخطيط ويخفيه وأبناءه عن التفاعل المعتاد وشجرة الوصول. visibility:hidden يحتفظ بالمساحة لكن يخفي العرض والتفاعل المعتاد. لا واحدة منهم بتحذف DOM نفسه.',
 'opacity:0 شفافية فقط؛ ممكن العنصر يفضل يستقبل الضغط والتركيز. pointer-events:none يمنع استهداف المؤشر لكنه مش حلًا وحده للكيبورد. لما تخفي قائمة أو حوار، فكّر في التركيز والوصول، مش فقط اللون والمساحة.');
 c('css-17','التدفق والمرجع في التموضع',
 'static هو موضع التدفق العادي. relative يسمح بإزاحة بصرية مع بقاء مكان العنصر الأصلي محسوبًا. absolute يخرج الصندوق من التدفق، لذلك العناصر الأخرى لا تحجز مكانه. قيم top وright وغيرها تقاس بالنسبة للحاوية المرجعية المناسبة.',
 'الأب المتموضع غير static غالبًا يوفر مرجعًا للابن absolute. لكن خصائص مثل transform ممكن تنشئ مرجعًا أيضًا. مجرد كتابة top لا يحرك عنصر static بالشكل المقصود. ابحث أولًا عن المرجع وقياساته ثم اضبط الإزاحة.');
 c('css-18','الثبات ومجال الالتصاق',
 'fixed غالبًا يرتبط بمساحة العرض ويبقى ظاهرًا مع التمرير، لكنه يخرج من التدفق فلا يحجز ارتفاعًا للهيدر. خصائص في الأسلاف قد تغير مرجعه. عوّض المساحة فقط لو التصميم يحتاج ذلك، واختبر ألا يغطي عناصر التركيز.',
 'sticky يبقى في التدفق ويبدأ الالتصاق عند حد زي top:0 ضمن مساحة حاويته وسياق التمرير. يحتاج مساحة فعلية للحركة. overflow في أسلافه قد يغير سياق التمرير، وارتفاع حاوية صغير قد يمنع ملاحظة الالتصاق. ده سلوك مختلف عن التحول لقيمة fixed.');
 c('css-19','ترتيب الطبقات داخل سياقاتها',
 'z-index يقارن ترتيب الصناديق داخل Stacking context. سياق جديد قد يتكون بسبب transform أو opacity أقل من 1 وخصائص أخرى. ابن بقيمة ضخمة لا يستطيع تجاوز سياق أب منخفض بمجرد زيادة الرقم.',
 'opacity تؤثر على العنصر ومحتواه كله كمجموعة. لو عايز خلفية شفافة ونص معتم، استخدم لونًا له قناة ألفا في الخلفية بدل تقليل opacity للصندوق. افحص الأسلاف لما نافذة أو قائمة تختفي خلف عنصر رغم رقم z-index كبير.');
 c('css-13','المحور الرئيسي مش ثابت أفقيًا',
 'display:flex يحدد حاوية؛ الأبناء المباشرون يصبحوا Flex items. flex-direction يحدد المحور الرئيسي: row حسب اتجاه السطر، وcolumn حسب اتجاه الكتلة. RTL يؤثر على البداية والنهاية، لذلك استخدم المصطلحين start وend بدل حفظ يمين ويسار.',
 'justify-content يوزع المساحة المتبقية على المحور الرئيسي. align-items يحاذي على المحور المتعامد. لو مفيش مساحة متبقية، تغيير justify-content قد لا يظهر فرقًا. لو محتاج محاذاة رأسية لازم أصلًا يكون فيه ارتفاع يسمح بمساحة.');
 c('css-14','الفرق بين توزيع الفراغ وتحديد المسافة',
 'gap مسافة بين العناصر وليست padding عند أطراف الحاوية. space-between يوزع الفراغ المتبقي بين العناصر ولا يضيفه عند الطرفين. ممكن تجمع gap مع توزيع مساحة؛ الأولى تحدد حد المسافة والثانية توزع الباقي.',
 'align-self يتجاوز محاذاة عنصر واحد. align-content يوزع خطوط flex في المحور المتعامد عندما يوجد أكثر من خط ومساحة متبقية؛ مش بديل align-items لكل حالة. اختبر بالقيم الفعلية وعدد الخطوط قبل اختيار الخاصية.');
 c('css-15','الانكماش والتمدد والانتقال لسطر',
 'flex-wrap:wrap يسمح بتكوين خطوط إضافية لما العناصر لا تناسب السطر. flex-basis الحجم الأساسي قبل توزيع المساحة، وflex-grow يحدد حصة التمدد، وflex-shrink يشارك في حساب الانكماش. الصيغة flex تجمعهم بهذا الترتيب: نمو ثم انكماش ثم أساس.',
 'الحد الأدنى التلقائي للمحتوى قد يمنع عنصر flex من الانكماش مع رابط طويل. min-width:0 على العنصر المناسب ولف النص يعالجان السبب في حالات شائعة. ما تستخدمش order لتغيير ترتيب القراءة الأساسي؛ الترتيب البصري لا يغير بالضرورة ترتيب الكيبورد والوثيقة.');
 c('css-16','الشبكة والمسارات والعناصر',
 'Grid تقسم الحاوية لمسارات صفوف وأعمدة. grid-template-columns تصف الأعمدة، وgap يفصلها. fr حصة من المساحة المتبقية بعد القيم والمسافات والقيود، وليست نسبة من العرض الكلي دائمًا. repeat تكرر وصف المسارات.',
 'minmax يحدد حدًا أدنى وأقصى للمسار. صيغة repeat(3,minmax(0,1fr)) تسمح للأعمدة بالانكماش بدون حد محتوى ضمني كبير. Grid items هي الأبناء المباشرون. اختيار Grid مناسب لما العلاقة بين الصفوف والأعمدة مهمة؛ Flexbox مناسب لتوزيع على محور رئيسي.');
 c('css-20','العلاقات والحالات في المحددات',
 'مسافة بين محددين تستهدف الأحفاد، و> تستهدف الأبناء المباشرين. + يختار الأخ التالي مباشرة، و~ يختار الإخوة اللاحقين المطابقين. [type="email"] يطابق خاصية بقيمة. لا تخلط وجود الخاصية بقيمة خاصية JavaScript الحالية.',
 ':hover حالة مؤشر، و:focus-visible حالة تركيز مرئي مناسبة حسب قرار المتصفح. :nth-child يحسب موضع العنصر بين إخواته. :not يستبعد المطابقة. المحدد المركب أدق لما له سبب، لكن سلاسل طويلة تربط CSS بتعشيش هش يصعب تغييره.');
 c('css-21','العناصر الوهمية مش عناصر DOM',
 '::before و::after ينشئوا صناديق مولّدة داخل العنصر بحسب CSS، ومش أبناء DOM عاديين تقدر تختارهم بـquerySelector. غالبًا تحتاج content حتى لو نصًا فارغًا لظهور الصندوق. الفرق عن :hover إنها جزء مولّد لا حالة.',
 'استخدمهم لزخرفة أو إشارة مكملة، وليس نصًا أساسيًا أو زرًا يحتاج تفاعلًا مستقلًا. التموضع والخلفية والقياسات تنطبق عليهم كصناديق ضمن القواعد. لو العنصر الأب فيه overflow:hidden قد يقص الزخرفة، فافحص القيد بدل زيادة z-index.');
 c('css-26','تعريف المتغير واستخدامه وسقوط القيمة',
 'Custom properties تبدأ بشرطتين زي --accent. تعريفها في :root يوفر قيمة عامة قابلة للوراثة، وتقدر تعيد تعريفها داخل حاوية لنطاقها. var(--accent) تستبدل القيمة عند حساب الخاصية.',
 'البديل في var(--accent,purple) يفيد عند غياب القيمة المناسبة، لكنه مش مدقق نوع يبدل أي قيمة غير صالحة لكل خاصية. المتغيرات خاضعة للـCascade والوراثة، فالوضع الداكن ممكن يبدل مجموعة قيم بدل تكرار قواعد كل مكون.');
 c('css-22','الانتقال محتاج قيمتين مختلفتين',
 'transition يحدد الخاصية والمدة ومنحنى السرعة والتأخير. لازم يحصل تغيير من قيمة قابلة للاستيفاء لقيمة أخرى؛ hover مجرد واحد من أسباب التغيير. منحنى ease يغير معدل الحركة داخل المدة، لا يغير المدة نفسها.',
 'ضع transition في الحالة الأساسية علشان الدخول والخروج يكونوا ناعمين. تجنب all بلا داعي، واختار transform أو opacity لما تكون مناسبة. وفر focus-visible للكيبورد؛ hover مش متاح بنفس المعنى على شاشات اللمس. احترام prefers-reduced-motion يسمح بتقليل الحركة لمن يحتاج.');
 c('css-23','التحويل البصري مش إعادة تخطيط',
 'transform يحوّل صندوق العنصر بصريًا: translate للإزاحة، rotate للدوران، scale للتكبير. مكان العنصر الأصلي في التدفق لا يتحول بنفس الطريقة، لذلك ممكن الشكل يغطي عنصرًا مجاورًا بدون دفعه.',
 'ترتيب دوال التحويل يؤثر على النتيجة لأن الإحداثيات بتتحول تباعًا. transform-origin نقطة المرجع للدوران والتكبير. transform قد ينشئ سياق تكديس ومرجعًا لبعض التموضع، فاختبر أثره على الأبناء المتموضعة بدل اعتباره حركة منعزلة.');
 c('css-24','تسلسل الحركة وتكرارها والتحكم فيها',
 '@keyframes تحدد قيمًا عند نسب زمنية من الدورة. 0% البداية و100% النهاية. animation-duration مدة الدورة، وiteration-count عدد الدورات، وinfinite تكرار مستمر. direction:alternate يجعل الاتجاه يتبادل بين الدورات.',
 'animation-fill-mode يحدد أثر القيم قبل أو بعد المدى النشط، وليس حفظًا دائمًا للتغييرات في المصدر. animation-play-state:paused يوقف الحركة في مكانها. لأي حركة مستمرة في محتوى قراءة وفر إيقافًا واضحًا، وما تستخدمش الوميض أو حركة النص كبديل لشرح الخطوة.');
 c('css-25','الظل لا يحجز مساحة',
 'box-shadow يرسم ظل الصندوق بقيم إزاحة أفقية ورأسية ثم تمويه وانتشار ولون. inset يجعل الظل داخليًا. الظل لا يوسّع مساحة التخطيط المحجوزة، وقد يقصه overflow في حاوية.',
 'text-shadow يخص أشكال الحروف، وdrop-shadow في filter يتبع قناع الشكل المرئي في حالات مختلفة عن مستطيل الصندوق. الظلال وسيلة فصل بصري؛ التباين والحدود تظل مهمة، خصوصًا في الوضع الداكن والمحتوى الطويل.');
 c('css-27','التجاوب قرار مبني على المحتوى',
 'Media query شرط يطبق قواعد CSS عند تطابق بيئة العرض. في الشاشات غالبًا نقارن العرض، لكن ممكن نفحص تفضيل الحركة أو الوضع اللوني. Breakpoint هو موضع تغيير التخطيط؛ اختاره عندما يحتاج المحتوى، وليس لأنه رقم جهاز محفوظ.',
 'التجاوب يضم عرضًا مرنًا ولفًا ومسافات وأزرارًا قابلة للاستخدام، مش Media queries فقط. اختبر بين المقاسات وليس نهاياتها. منع التمرير الأفقي للصفحة يبدأ بتحديد العنصر الخارج، لا إخفاء overflow على body لإخفاء المشكلة.');
 const responsiveNotes=[
 ['responsive-1','الهدف من التصميم المتجاوب','المستخدم قد يفتح الموقع بنافذة ضيقة على كمبيوتر أو يكبر النص، لذلك عرض الشاشة مش اسم الجهاز. ابدأ بمحتوى له ترتيب منطقي وقابل للالتفاف، ثم حدد متى الأعمدة تتحول لصف واحد.','اختبر النص الأطول المتوقع، مش كلمات قصيرة فقط. الأزرار لازم تفضل قابلة للضغط والعناوين ما تغطيش بعضها. التفاعل بالكيبورد واللمس جزء من التجاوب، والشرح لازم يظل كاملًا مهما صغر العرض.'],
 ['responsive-2','عرض التخطيط على الهاتف','meta viewport بقيمة width=device-width تجعل عرض التخطيط يوافق عرض الجهاز بوحدات CSS، وinitial-scale=1 نقطة بداية التكبير. بدونه قد تتصرف media queries على عرض افتراضي أوسع وتظهر الصفحة مصغرة.','لا تمنع تكبير المستخدم بـuser-scalable=no أو حد أقصى جامد. تفعيل viewport لا يصلح عرضًا ثابتًا كبيرًا؛ لازم CSS نفسها تسمح بتقلص الحاويات ولف النص.'],
 ['responsive-3','المرونة لا تعني منع px','rem مناسبة لحجم قابل للتكيف مع خط الجذر، و% للعرض بالنسبة للمرجع، وpx مفيدة لحدود أو قيم محددة. اختيار الوحدة حسب الخاصية؛ كل الوحدات لها استخدامات صحيحة.','استخدم حدودًا مع المرونة مثل عرض 100% وmax-width. مع padding تأكد من box-sizing. الحساب النهائي يتأثر بالحد الأدنى للمحتوى، فلا تعالج كل مشكلة بتغيير الوحدة فقط.'],
 ['responsive-4','العرض المطلوب وحدّه الأعلى','width يحدد العرض المطلوب ضمن قيود التخطيط. max-width يحد أقصاه؛ width:100% مع max-width:800px يعني ملء المتاح لحد 800. القاعدة لا تضيف توسطًا تلقائيًا؛ تحتاج هوامش مناسبة لو ده الهدف.','height ثابت مع نص متغير خطر لأن النص قد يزيد أو يكبر. اترك الارتفاع للمحتوى غالبًا، وحدد حدودًا فقط عند حاجة واضحة. max-width للصور يمنع خروجها وheight:auto يحافظ على النسبة.'],
 ['responsive-5','ترتيب الشروط جزء من النتيجة','قاعدة داخل Media query لا تكسب الأولوية لمجرد وجودها في شرط. بعد تطابق الشرط تدخل نفس نظام Cascade وSpecificity. إذا كانت القواعد بنفس الوزن، ترتيبها في الملف يحسم التعارض.','min-width يعني من هذا العرض وما فوق، وmax-width يعني حتى هذا العرض. اكتب الشروط بطريقة تقلل تعارضات الحدود، واختبر عرضًا قبل الحد وعنده وبعده.'],
 ['responsive-6','ابدأ بالقواعد الأبسط','Mobile-first يعني قواعد البداية تناسب المساحة الضيقة ثم تضيف تحسينات بـmin-width. Desktop-first يبدأ بتخطيط أوسع ثم يعدل للمساحات الأقل. الاتنين ممكن، لكن اختيار خطة واحدة يسهل متابعة القواعد.','بدء الموبايل مش حذف محتوى أساسي. ابدأ بعمود واحد واضح، ثم حوّل مناطق مناسبة لأعمدة لما يوجد عرض كافٍ. ترتيب DOM يظل منطقيًا في الحالتين.'],
 ['responsive-7','خلي العناصر تتنفس وتلف','flex-wrap يسمح بسطور إضافية وgap يضمن مسافة ثابتة. أساس عنصر مرن مثل flex:1 1 240px يقترح حجمًا مع السماح بالتوزيع. افهم أن حدود المحتوى قد تمنع الانكماش.','ضع min-width:0 على عنصر يحتاج لف نص طويل، ولا تستخدم order لتغيير قصة القراءة. شريط الأزرار ممكن يلف بدل الخروج؛ وقتها اختبر بقاء كل زر واضحًا وبحجم مناسب.'],
 ['responsive-8','عدد الأعمدة يتبع المساحة','auto-fit مع repeat وminmax ينشئ عدد مسارات يناسب الحاوية، وقد يطوي المسارات الفارغة لتتمدد الباقية. auto-fill يحتفظ بمساحة المسارات الفارغة؛ الاختيار يتحدد بالسلوك المطلوب.','حد أدنى أكبر من عرض الهاتف قد يسبب خروجًا حتى مع Grid مرنة. اختيار min(100%,240px) كحد أدنى في صيغة مناسبة يسمح بالانكماش داخل حاوية أضيق. افحص المسافات والحدود ضمن الحساب.'],
 ['responsive-9','نسبة الوسيط وملف التحميل','img بعرض أقصى 100% وارتفاع auto تحافظ على النسبة. object-fit:cover مفيدة داخل صندوق له أبعاد محددة لكنها قد تقص الصورة، وcontain تحافظ على ظهور كامل المحتوى.','srcset وsizes يساعدان المتصفح يختار ملفًا مناسبًا، مش مجرد تصغير صورة ضخمة بـCSS. الفيديو والإطارات تحتاج نسبة أبعاد مناسبة. حدد أبعادًا أو aspect-ratio لتقليل تحرك التخطيط عند التحميل.'],
 ['responsive-10','حد أدنى وحجم مرن وحد أقصى','clamp تستقبل حدًا أدنى وقيمة مفضلة وحدًا أقصى. المتصفح يختار المفضلة مع تقييدها بالحدين. في الخطوط جمع rem مع جزء vw يحافظ على جزء قابل لتفضيل المستخدم بدل الاعتماد على عرض الشاشة وحده.','اختبر تكبير النص 200% وطول العنوان. حجم عنوان مناسب لا يبرر تقليل ارتفاع السطر حتى تتداخل الحروف. حافظ على عرض فقرة مقروء وأحجام غير متطرفة عند أطراف الشاشة.'],
 ['responsive-11','التبديل البصري يحتاج مراجعة تفاعل','إخفاء قائمة سطح المكتب وإظهار زر للموبايل لازم يصاحبه تحكم واضح في القائمة وaria-expanded صحيح. ما تسيبش عناصر مخفية بصريًا قابلة للتركيز في مسار غير مرئي.','لا تخفي معلومات أساسية لأن عرض الشاشة أقل. فرق بين تغيير العرض وتأجيل تفاصيل اختيارية داخل عنصر قابل للفتح. احترم تفضيل تقليل الحركة عند تغيير الحالات.'],
 ['responsive-12','اعرف مصدر الخروج قبل إصلاحه','قارن scrollWidth بعرض النافذة وافحص العناصر الأعرض في أدوات المطور. أسباب شائعة: width ثابت، نص بلا كسر، min-width ضمني، صورة كبيرة أو padding خارج حساب العرض.','pre والجداول ممكن تحتاج تمريرًا محليًا مقصودًا، لكن الصفحة نفسها لا ينبغي أن تتحرك أفقيًا بسببها. ما تعالجش كل شيء بـoverflow-x:hidden؛ ممكن تخفي زرارًا أو نصًا وتترك السبب كما هو.']
 ];
 responsiveNotes.forEach(([id,t,...p])=>c(id,t,...p));

 /* JavaScript and React notes are installed in the companion file. */
})();
